package redact

import (
	"bytes"
	"sort"
	"strings"

	"sigs.k8s.io/structured-merge-diff/v6/fieldpath"

	"setdrift.io/setdrift-engine/pkg/resource"
)

// People and the tools they apply configuration with. A Secret key written
// only by other field managers was generated by a controller (an operator
// names itself, e.g. argocd-server, external-secrets, cert-manager).
var (
	toolManagers = map[string]bool{
		"helm": true, "argocd-controller": true, "kustomize-controller": true, "helm-controller": true,
		"Go-http-client": true, "OpenAPI-Generator": true, "python-requests": true, "kubernetes-dashboard": true,
		// GitLab agent for Kubernetes (gitlab-agent internal/api FieldManager)
		"agentk": true,
		// Rancher Fleet's agent, which applies through the Helm SDK: Helm names the manager after the binary
		"fleetagent": true,
	}
	toolPrefixes = []string{"kubectl", "helm", "terraform", "Terraform", "pulumi", "kapp", "kpt", "k9s", "setdrift",
		// Crossplane provider-kubernetes Objects: provider-kubernetes/<Object name>
		"provider-kubernetes/"}
)

func tool(manager string) bool {
	if toolManagers[manager] {
		return true
	}
	for _, p := range toolPrefixes {
		if strings.HasPrefix(manager, p) {
			return true
		}
	}
	return false
}

// keyOwners returns, for each key under field (data or stringData), the
// field managers that own it.
func keyOwners(o *resource.Object, field string) map[string][]string {
	out := map[string][]string{}
	m, _ := o.Object[field].(map[string]any)
	if len(m) == 0 {
		return out
	}
	for _, e := range o.GetManagedFields() {
		if e.FieldsV1 == nil {
			continue
		}
		set := fieldpath.NewSet()
		if set.FromJSON(bytes.NewReader(e.FieldsV1.Raw)) != nil {
			// Unreadable: count it as a person, the safe side.
			for k := range m {
				out[k] = append(out[k], "unknown")
			}
			continue
		}
		for k := range m {
			if set.Has(fieldpath.MakePathOrDie(field, k)) {
				out[k] = append(out[k], e.Manager)
			}
		}
	}
	return out
}

// generated reports whether a key's owners are all controllers, and names
// them. A key with no recorded owner (manifests read from files) counts as
// a person's.
func generated(owners []string) (string, bool) {
	if len(owners) == 0 {
		return "", false
	}
	for _, m := range owners {
		if tool(m) || m == "unknown" {
			return "", false
		}
	}
	sort.Strings(owners)
	return strings.Join(owners, ","), true
}
